<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Minimalist Kanban Board</title>
    <style>
        :root {
            --bg-color: #f8fafc;
            --column-bg: #f1f5f9;
            --card-bg: #ffffff;
            --text-main: #0f172a;
            --text-muted: #64748b;
            --primary: #4f46e5;
            --primary-hover: #4338ca;
            --border-color: #cbd5e1;
            --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
            --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.5;
            padding: 2.5rem 1.5rem;
        }

        .app-container {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 2.5rem;
        }

        .app-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 1.5rem;
        }

        .app-header h1 {
            font-size: 1.85rem;
            font-weight: 800;
            letter-spacing: -0.025em;
            color: #1e293b;
        }

        .card-creator {
            display: flex;
            gap: 0.625rem;
            flex-grow: 1;
            max-width: 480px;
        }

        #new-card {
            flex-grow: 1;
            padding: 0.625rem 1rem;
            font-size: 0.95rem;
            border: 1px solid var(--border-color);
            border-radius: 8px;
            background: white;
            color: var(--text-main);
            transition: border-color 0.15s, box-shadow 0.15s;
        }

        #new-card:focus {
            outline: none;
            border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
        }

        #add-card {
            background-color: var(--primary);
            color: white;
            border: none;
            padding: 0.625rem 1.25rem;
            font-size: 0.95rem;
            font-weight: 600;
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.15s;
            white-space: nowrap;
        }

        #add-card:hover {
            background-color: var(--primary-hover);
        }

        .board {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 1.5rem;
            align-items: flex-start;
        }

        @media (max-width: 768px) {
            .board {
                grid-template-columns: 1fr;
            }
            .app-header {
                flex-direction: column;
                align-items: stretch;
            }
            .card-creator {
                max-width: 100%;
            }
        }

        .column {
            background-color: var(--column-bg);
            border-radius: 12px;
            padding: 1.25rem;
            display: flex;
            flex-direction: column;
            gap: 1rem;
            min-height: 550px;
            border: 2px dashed transparent;
            transition: border-color 0.2s, background-color 0.2s;
        }

        .column.drag-over {
            background-color: #e2e8f0;
            border-color: var(--primary);
        }

        .column-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            user-select: none;
        }

        .column-header h2 {
            font-size: 1.1rem;
            font-weight: 700;
            color: #334155;
        }

        .count {
            background-color: #cbd5e1;
            color: #334155;
            font-size: 0.8rem;
            font-weight: 700;
            padding: 0.15rem 0.6rem;
            border-radius: 9999px;
            transition: background-color 0.15s, color 0.15s;
        }

        .card-container {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
            flex-grow: 1;
        }

        .card {
            background-color: var(--card-bg);
            border-radius: 8px;
            padding: 1rem;
            box-shadow: var(--shadow-sm);
            border: 1px solid rgba(226, 232, 240, 0.8);
            cursor: grab;
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            gap: 0.75rem;
            transition: transform 0.1s, box-shadow 0.15s, opacity 0.15s;
            position: relative;
        }

        .card:hover {
            box-shadow: var(--shadow-md);
        }

        .card:active {
            cursor: grabbing;
        }

        .card.dragging {
            opacity: 0.4;
            transform: scale(0.98);
            box-shadow: none;
        }

        /* Prevents weird dragover flickering on nested card contents */
        body.dragging-active .card * {
            pointer-events: none;
        }

        .card-text {
            font-size: 0.95rem;
            color: #1e293b;
            word-break: break-word;
            white-space: pre-wrap;
            line-height: 1.4;
        }

        .card-del {
            background: none;
            border: none;
            color: var(--text-muted);
            font-size: 1.25rem;
            line-height: 1;
            cursor: pointer;
            padding: 0.1rem 0.35rem;
            border-radius: 4px;
            transition: color 0.1s, background-color 0.1s;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .card-del:hover {
            color: #ef4444;
            background-color: #fee2e2;
        }
    </style>
</head>
<body>

    <div class="app-container">
        <header class="app-header">
            <h1>Workspace</h1>
            <div class="card-creator">
                <input type="text" id="new-card" placeholder="Add a new task..." aria-label="Task content">
                <button id="add-card">Add Card</button>
            </div>
        </header>

        <main class="board">
            <!-- To Do Column -->
            <section class="column" id="col-todo">
                <header class="column-header">
                    <h2>To Do</h2>
                    <span class="count">0</span>
                </header>
                <div class="card-container"></div>
            </section>

            <!-- Doing Column -->
            <section class="column" id="col-doing">
                <header class="column-header">
                    <h2>Doing</h2>
                    <span class="count">0</span>
                </header>
                <div class="card-container"></div>
            </section>

            <!-- Done Column -->
            <section class="column" id="col-done">
                <header class="column-header">
                    <h2>Done</h2>
                    <span class="count">0</span>
                </header>
                <div class="card-container"></div>
            </section>
        </main>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const todoContainer = document.querySelector('#col-todo .card-container');
            const doingContainer = document.querySelector('#col-doing .card-container');
            const doneContainer = document.querySelector('#col-done .card-container');

            const containers = {
                todo: todoContainer,
                doing: doingContainer,
                done: doneContainer
            };

            const newCardInput = document.getElementById('new-card');
            const addCardButton = document.getElementById('add-card');

            // Loads cards from storage, or fallback to default starter state
            function loadBoard() {
                const saved = localStorage.getItem('kanban-board-state');
                let state;

                if (saved) {
                    state = JSON.parse(saved);
                } else {
                    state = {
                        todo: [
                            { id: 'card-default-1', text: '📋 Research standard UX layout patterns' },
                            { id: 'card-default-2', text: '🎨 Outline color palette in design system' }
                        ],
                        doing: [
                            { id: 'card-default-3', text: '⚡ Drag cards around to test features' }
                        ],
                        done: [
                            { id: 'card-default-4', text: '🎉 Verify local storage persistence' }
                        ]
                    };
                }

                // Render out elements
                Object.keys(containers).forEach(colKey => {
                    const container = containers[colKey];
                    container.innerHTML = '';
                    if (state[colKey]) {
                        state[colKey].forEach(cardData => {
                            const cardEl = createCard(cardData.id, cardData.text);
                            container.appendChild(cardEl);
                        });
                    }
                });

                updateCounts();
            }

            // Gathers current DOM cards and serializes to localStorage
            function saveBoard() {
                const state = {
                    todo: [],
                    doing: [],
                    done: []
                };

                Object.keys(containers).forEach(colKey => {
                    const cards = containers[colKey].querySelectorAll('.card');
                    cards.forEach(card => {
                        state[colKey].push({
                            id: card.id,
                            text: card.querySelector('.card-text').innerText
                        });
                    });
                });

                localStorage.setItem('kanban-board-state', JSON.stringify(state));
                updateCounts();
            }

            // Updates count bubble content
            function updateCounts() {
                Object.keys(containers).forEach(colKey => {
                    const count = containers[colKey].querySelectorAll('.card').length;
                    const columnEl = document.getElementById(`col-${colKey}`);
                    columnEl.querySelector('.count').innerText = count;
                });
            }

            // Card DOM element constructor
            function createCard(id, text) {
                const card = document.createElement('div');
                card.classList.add('card');
                card.id = id;
                card.setAttribute('draggable', 'true');

                const textSpan = document.createElement('span');
                textSpan.classList.add('card-text');
                textSpan.innerText = text;

                const delBtn = document.createElement('button');
                delBtn.classList.add('card-del');
                delBtn.innerHTML = '&times;';
                delBtn.setAttribute('aria-label', 'Delete item');

                // Delete handlers
                delBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    card.remove();
                    saveBoard();
                });

                // HTML5 Drag Event Bindings
                card.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', card.id);
                    card.classList.add('dragging');
                    document.body.classList.add('dragging-active');
                });

                card.addEventListener('dragend', () => {
                    card.classList.remove('dragging');
                    document.body.classList.remove('dragging-active');
                });

                card.appendChild(textSpan);
                card.appendChild(delBtn);

                return card;
            }

            // Creates and pushes cards into "To Do"
            function addNewCard() {
                const text = newCardInput.value.trim();
                if (!text) return;

                // Simple collision-free local unique ID logic
                const cardId = 'card-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);
                const cardEl = createCard(cardId, text);
                todoContainer.appendChild(cardEl);

                newCardInput.value = '';
                saveBoard();
            }

            addCardButton.addEventListener('click', addNewCard);
            newCardInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    addNewCard();
                }
            });

            // Column Drag and Drop Handlers
            const columns = document.querySelectorAll('.column');
            columns.forEach(column => {
                column.addEventListener('dragover', (e) => {
                    e.preventDefault(); // Required logic to allow drops
                    column.classList.add('drag-over');
                });

                column.addEventListener('dragleave', () => {
                    column.classList.remove('drag-over');
                });

                column.addEventListener('drop', (e) => {
                    e.preventDefault();
                    column.classList.remove('drag-over');

                    const cardId = e.dataTransfer.getData('text/plain');
                    const cardEl = document.getElementById(cardId);
                    if (cardEl) {
                        const targetContainer = column.querySelector('.card-container');
                        targetContainer.appendChild(cardEl);
                        saveBoard();
                    }
                });
            });

            // Bootstrap setup
            loadBoard();
        });
    </script>
</body>
</html>
